// @ts-nocheck
import { clamp, wrapText } from './utils.js';
import { roundRect, evalPreset, ease, IN_PRESETS, unitOffsets, EASINGS } from './motion.js';
import { drawDynamicCaption, isDynamicLayout, canonicalLayoutId, DYNAMIC_LAYOUTS, DYNAMIC_SAMPLES, sampleCueForStyle } from './dynamic-captions.js';

export { isDynamicLayout, canonicalLayoutId, DYNAMIC_LAYOUTS, DYNAMIC_SAMPLES, sampleCueForStyle, EASINGS, IN_PRESETS };

export function drawSubtitle(ctx, cue, srcT, W, H, styleOverride = null) {
  // A picked set of styles rotates a paragraph at a time. Resolving it here
  // means the stage, both export paths and the thumbnails agree by
  // construction. A card preview passes its own style and never rotates.
  const st = styleOverride;
  // Motion-text captions: a template from the Motion text library paints the
  // cue. It can decline (unknown template, empty line), and then the caption
  // falls through to the normal renderer rather than disappearing.
  if (isDynamicLayout(st.dynamicLayout)) {
    const box = drawDynamicCaption(ctx, cue, srcT, W, H, st);
    return box;
  }
  let fontSize = (st.size / 100) * H;
  const safeFont = String(st.font || 'Inter').replace(/["']/g, '');
  const fontFamily = safeFont.includes(' ') ? `"${safeFont}"` : safeFont;
  const setCanvasFont = () => { ctx.font = `${st.italic ? 'italic ' : ''}${st.weight} ${fontSize}px ${fontFamily}, Inter, Arial, sans-serif`; };
  setCanvasFont();
  ctx.textAlign = 'left';
  ctx.textBaseline = 'alphabetic';

  let text = cue.text;
  if (st.uppercase) text = text.toUpperCase();
  const maxWidth = W * clamp(Number(st.maxWidth) || 0.82, 0.5, 0.94);
  let lines = wrapText(ctx, text, maxWidth);
  const maxLines = Math.max(0, Math.round(Number(st.maxLines) || 0));
  // Keep every word while honoring a two-line social safe zone: reduce only
  // as much as needed, with a floor that remains legible on mobile exports.
  while (maxLines && lines.length > maxLines && fontSize > H * 0.035) {
    fontSize *= 0.94;
    setCanvasFont();
    lines = wrapText(ctx, text, maxWidth);
  }
  const lineH = fontSize * clamp(Number(st.lineHeight) || 1.3, 0.95, 1.6);
  const blockH = lines.length * lineH;

  // Caption-card metrics (the "Live Captions" white podcast card): a stable
  // card width with left-aligned text and a dot-bar audio row, so the card
  // doesn't resize with every cue and the wave never crowds the words.
  const card = st.captionCard ? {
    padX: fontSize * 0.6,
    padTop: fontSize * 0.55,
    waveH: st.audioWave ? fontSize * 0.26 : 0,
    waveGap: st.audioWave ? fontSize * 0.55 : 0,
    padBottom: fontSize * 0.5,
    w: maxWidth + fontSize * 1.2,
  } : null;
  if (card) card.h = blockH + card.padTop + card.waveGap + card.waveH + card.padBottom;

  // Free placement: st.posX / st.posY (percent of frame, the CENTER of the
  // caption block) — set by dragging the caption on the stage with grid
  // snapping. Falls back to the classic top/middle/bottom enum when unset.
  const posXFrac = Number.isFinite(st.posX) ? clamp(st.posX, 0, 100) / 100 : 0.5;
  const anchorX = W * posXFrac;
  let baseY;
  const margin = H * 0.055;
  if (card) {
    // Center the WHOLE card (text + wave row) on the anchor point; anchoring
    // just the text block made the card hang visibly low.
    const cardTop = Number.isFinite(st.posY)
      ? H * (clamp(st.posY, 0, 100) / 100) - card.h / 2
      : st.position === 'top' ? margin
      : st.position === 'middle' ? H / 2 - card.h / 2
      : H - margin - card.h;
    baseY = cardTop + card.padTop + fontSize;
  } else if (Number.isFinite(st.posY)) {
    baseY = H * (clamp(st.posY, 0, 100) / 100) - blockH / 2 + fontSize;
  } else if (st.position === 'top') baseY = margin + fontSize;
  else if (st.position === 'middle') baseY = H / 2 - blockH / 2 + fontSize;
  else baseY = H - margin - blockH + fontSize;

  // Record the on-canvas caption rect (live render only, not preview thumbs)
  // so the stage pointer interaction can hit-test and drag it.
  if (false) {
    if (card) {
      void { x: anchorX - card.w / 2, y: baseY - fontSize - card.padTop, w: card.w, h: card.h };
    } else {
      const maxLineW = lines.reduce((m, line) => Math.max(m, ctx.measureText(line).width), 0);
      void {
        x: anchorX - maxLineW / 2 - fontSize * 0.45,
        y: baseY - fontSize - fontSize * 0.3,
        w: maxLineW + fontSize * 0.9,
        h: blockH + fontSize * 0.55,
      };
    }
  }

  const anim = st.anim && st.anim.preset && st.anim.preset !== 'none' ? st.anim : null;
  const unit = anim ? (anim.unit || 'word') : 'word';
  // Word timings must line up 1:1 with the displayed words; after external
  // edits they can drift, which silently kills karaoke highlighting. When the
  // counts disagree, spread timings evenly instead of highlighting nothing.
  let timed = cue.words && cue.words.length ? cue.words : null;
  const displayWordCount = text.split(/\s+/).filter(Boolean).length;
  // Cues without word timings (manually added lines, imported SRT, some
  // translations) or with a count that no longer matches the text get even
  // synthetic timings — EVERY cue must track word-by-word, not just the
  // transcribed ones.
  if ((!timed || timed.length !== displayWordCount) && displayWordCount > 0) {
    const span = (cue.end - cue.start) / displayWordCount;
    timed = Array.from({ length: displayWordCount }, (_, i) => ({
      start: cue.start + i * span, end: cue.start + (i + 1) * span,
    }));
  }
  // Speech has silent gaps between words; a highlight that switches off in
  // every gap reads as broken tracking. Each word stays active until the next
  // one starts (last word holds until the cue ends).
  if (timed) {
    timed = timed.map((w, i) => ({
      ...w,
      end: Math.min(cue.end, Math.max(w.end, timed[i + 1] ? timed[i + 1].start : cue.end)),
    }));
  }
  const spaceW = ctx.measureText(' ').width;
  const scale1080 = H / 1080;
  const dur = anim ? Math.max(anim.duration || 0.3, 0.05) : 0.3;

  // A hard cut when a cue ends reads as unpolished next to a proper fade —
  // every style gets this exit softening for free, no preset changes needed.
  const EXIT_FADE_DUR = 0.12;
  const remainingToEnd = cue.end - srcT;
  const exitFade = remainingToEnd < EXIT_FADE_DUR
    ? ease('slowdown', clamp(remainingToEnd / EXIT_FADE_DUR, 0, 1), 1)
    : 1;

  const drawBoxes = () => {
    if (card) {
      const cardX = anchorX - card.w / 2;
      const cardY = baseY - fontSize - card.padTop;
      ctx.fillStyle = st.captionCardColor || '#f4f4f0';
      roundRect(ctx, cardX, cardY, cardX + card.w > W ? W - cardX : card.w, card.h, fontSize * 0.55);
      ctx.fill();

      if (st.audioWave) {
        // Left-aligned row of horizontal dot-pills that breathe with the
        // audio phase — reads as a live voice indicator, not an equalizer.
        const dotH = card.waveH;
        const gap = dotH * 0.7;
        const cy = cardY + card.h - card.padBottom - dotH / 2;
        const phase = Math.max(0, srcT - cue.start);
        let x = cardX + card.padX;
        for (let i = 0; i < 8; i++) {
          const pulse = 0.5 + 0.5 * Math.sin(phase * (3.6 + i * 0.31) + i * 1.9);
          const wPill = dotH * (0.9 + pulse * 1.7);
          ctx.fillStyle = st.waveColor || '#2f2f2f';
          ctx.globalAlpha *= 0.45 + pulse * 0.55;
          roundRect(ctx, x, cy - dotH / 2, wPill, dotH, dotH / 2);
          ctx.fill();
          ctx.globalAlpha /= 0.45 + pulse * 0.55;
          x += wPill + gap;
        }
      }
      return;
    }
    if (!(st.bgOn && st.bg && st.bg !== 'transparent')) return;
    lines.forEach((line, i) => {
      const ly = baseY + i * lineH;
      const lw = ctx.measureText(line).width;
      const padX = fontSize * 0.42, padY = fontSize * 0.26;
      ctx.fillStyle = st.bg;
      roundRect(ctx, anchorX - lw / 2 - padX, ly - fontSize - padY * 0.6,
        lw + padX * 2, fontSize + padY * 2, fontSize * (st.bgRadius != null ? st.bgRadius : 0.22));
      ctx.fill();
    });
  };

  let wordIdx = 0;
  const allWords = [];
  lines.forEach((line, i) => {
    const ly = baseY + i * lineH;
    const lw = ctx.measureText(line).width;
    // Card captions read left-aligned (podcast style); everything else centers.
    let cx = card ? anchorX - card.w / 2 + card.padX : anchorX - lw / 2;
    for (const part of line.split(' ')) {
      if (!part) continue;
      allWords.push({ text: part, x: cx, y: ly, w: ctx.measureText(part).width, idx: wordIdx });
      cx += ctx.measureText(part).width + spaceW;
      wordIdx++;
    }
  });

  // apply an animation pose to the context around a pivot point
  const applyPose = (pose, cxp, cyp) => {
    ctx.globalAlpha *= pose.opacity;
    ctx.translate(cxp + pose.dx * fontSize, cyp + pose.dy * fontSize);
    ctx.scale(Math.max(pose.scale * pose.scaleX, 0.001), Math.max(pose.scale * pose.scaleY, 0.001));
    ctx.rotate(pose.rot * Math.PI / 180);
    ctx.translate(-cxp, -cyp);
    if (pose.blur > 0.2) ctx.filter = `blur(${pose.blur * scale1080}px)`;
  };
  // Karaoke word-pop as a spring ease in/out of the active window instead of
  // a hard binary snap — reuses the engine's own overshoot curve rather than
  // a fixed scale flip, so the pop reads as motion instead of a glitch.
  const KARAOKE_POP_RAMP = 0.08;
  const karaokeScale = (active, wInfo) => {
    if (!active || !wInfo) return 1;
    const since = clamp((srcT - wInfo.start) / KARAOKE_POP_RAMP, 0, 1);
    const until = clamp((wInfo.end - srcT) / KARAOKE_POP_RAMP, 0, 1);
    const e = Math.min(ease('overshoot', since, 1), ease('overshoot', until, 1));
    return 1 + 0.09 * e;
  };
  const poseAt = (t0, i) => {
    const p = (srcT - t0) / dur;
    if (p <= 0) return 'hidden';
    if (p >= 1) return null; // at rest
    const e = ease(anim.ease || 'overshoot', p, anim.intensity || 1);
    const pose = evalPreset(IN_PRESETS, anim.preset, e, anim.intensity || 1, i);
    if (pose && (!pose.visible || pose.opacity <= 0.003)) return 'hidden';
    return pose;
  };
  const paintText = (text, x, y, active, wRect, highlighted = active) => {
    // viral "box word": the spoken word gets a filled card behind it
    if (active && st.highlightBox && wRect && wRect.box !== false) {
      const padX = fontSize * 0.26, padY = fontSize * 0.18;
      ctx.fillStyle = st.highlightBoxColor || '#b7ff19';
      roundRect(ctx, wRect.x - padX, y - fontSize - padY * 0.5,
        wRect.w + padX * 2, fontSize + padY * 2, fontSize * 0.42);
      ctx.fill();
    }
    // Mixed-typography emphasis: the highlighted word can render in its own
    // font (e.g. a script face inside a bold sans line). Layout still uses
    // the base font's widths, so keep emphasis faces roughly similar width.
    // The tracked word may use its own font and/or size. Scale is clamped so
    // a big highlight face can't blow past the caption box, and the restyled
    // word is re-centered over its base-layout slot so it never sits skewed.
    const hlScale = clamp(Number(st.highlightScale) || 1, 0.7, 1.5);
    const altFont = highlighted && (st.highlightFont || Math.abs(hlScale - 1) > 0.01);
    if (altFont) {
      ctx.save()
      const hlFamily = String(st.highlightFont || st.font).replace(/["']/g, '')
      ctx.font = `${st.highlightItalic ? 'italic ' : ''}${st.weight} ${fontSize * hlScale}px "${hlFamily}", ${st.highlightFont ? 'cursive' : 'sans-serif'}`
      if (wRect) {
        const mw = ctx.measureText(text).width;
        x += (wRect.w - mw) / 2;
      }
    }
    if (st.pixel3d) {
      const blackStroke = Math.max(2, fontSize * 0.18);
      const whiteRim = Math.max(1.5, fontSize * 0.045);
      const depth = Math.max(2, fontSize * 0.13);
      ctx.save();
      ctx.shadowColor = 'transparent'; ctx.shadowBlur = 0;
      ctx.lineJoin = 'miter'; ctx.miterLimit = 3;
      ctx.strokeStyle = '#f5f5e8'; ctx.lineWidth = blackStroke + whiteRim * 2;
      ctx.strokeText(text, x + depth, y + depth);
      ctx.strokeStyle = '#050505'; ctx.lineWidth = blackStroke;
      ctx.strokeText(text, x + depth, y + depth);
      ctx.fillStyle = '#151515'; ctx.fillText(text, x + depth, y + depth);
      ctx.restore();
    }
    if (st.dropShadow && !st.glow) {
      ctx.shadowColor = st.kineticPhrase ? 'rgba(0,0,0,0.45)' : 'rgba(0,0,0,0.85)';
      ctx.shadowBlur = fontSize * 0.16;
      ctx.shadowOffsetX = fontSize * 0.045;
      ctx.shadowOffsetY = fontSize * 0.11;
    }
    if (st.glow) {
      ctx.shadowColor = st.glowColor || st.color;
      ctx.shadowBlur = (st.glowSize || 18) * scale1080 * 1.6;
    }
    if (st.outline && (st.outlineW == null || st.outlineW > 0.05)) {
      const outlineWidth = Math.max(1.5, fontSize * 0.1 * (st.outlineW != null ? st.outlineW : 1));
      if (st.pixel3d) {
        ctx.lineWidth = outlineWidth + Math.max(1.5, fontSize * 0.045) * 2;
        ctx.strokeStyle = '#f5f5e8';
        ctx.lineJoin = 'miter'; ctx.miterLimit = 3;
        ctx.strokeText(text, x, y);
      }
      ctx.lineWidth = outlineWidth;
      ctx.strokeStyle = st.outlineColor;
      ctx.lineJoin = st.pixel3d ? 'miter' : 'round';
      ctx.miterLimit = st.pixel3d ? 3 : 2;
      ctx.strokeText(text, x, y);
    }
    let fill = (st.highlightWords && highlighted) ? st.highlightColor : st.color;
    if (active && st.highlightBox) fill = st.highlightTextColor || '#0a0d05';
    else if (st.wordAlt && wRect) fill = wRect.idx % 2 ? (st.color2 || '#b7ff19') : st.color;
    else if (st.gradient && st.color2 && !(st.highlightWords && highlighted)) {
      const g = ctx.createLinearGradient(0, y - fontSize, 0, y + fontSize * 0.2);
      g.addColorStop(0, st.color);
      g.addColorStop(1, st.color2);
      fill = g;
    }
    ctx.fillStyle = fill;
    ctx.fillText(text, x, y);
    if (altFont) ctx.restore();
  };

  // ---- unit: whole caption — one pose around the block's center ----
  if (anim && unit === 'none') {
    const pose = poseAt(cue.start, 0);
    if (pose === 'hidden') return;
    ctx.save();
    ctx.globalAlpha *= exitFade;
    if (st.kineticPhrase) {
      const elapsed = Math.max(0, srcT - cue.start);
      const remaining = Math.max(0, cue.end - srcT);
      const entrance = clamp(elapsed / 0.23, 0, 1);
      const scale = entrance < 0.65
        ? 0.86 + (1.03 - 0.86) * (entrance / 0.65)
        : 1.03 + (1 - 1.03) * ((entrance - 0.65) / 0.35);
      ctx.globalAlpha *= Math.min(1, elapsed / 0.11, remaining / 0.09);
      const pivotY = baseY - fontSize + blockH / 2;
      ctx.translate(anchorX, pivotY); ctx.scale(scale, scale); ctx.translate(-anchorX, -pivotY);
    } else if (pose) applyPose(pose, anchorX, baseY - fontSize + blockH / 2);
    drawBoxes();
    for (const wd of allWords) {
      const wInfo = timed ? timed[wd.idx] : null;
      const active = wInfo && srcT >= wInfo.start && srcT <= wInfo.end;
      const highlighted = !!wInfo && (st.progressiveHighlight ? srcT >= wInfo.start : active);
      ctx.save();
      if (st.karaokePop) {
        const kScale = karaokeScale(active, wInfo);
        if (kScale !== 1) {
          const cxp = wd.x + wd.w / 2, cyp = wd.y - fontSize * 0.36;
          ctx.translate(cxp, cyp); ctx.scale(kScale, kScale); ctx.translate(-cxp, -cyp);
        }
      }
      paintText(wd.text, wd.x, wd.y, active, { x: wd.x, w: wd.w, idx: wd.idx }, highlighted);
      ctx.restore();
    }
    ctx.restore();
    return;
  }

  // ---- unit: word (voice-timed) or letter (cascade within each word) ----
  ctx.save();
  ctx.globalAlpha *= exitFade;
  drawBoxes();
  const offs = anim ? unitOffsets({ unit: 'word', stagger: anim.stagger != null ? anim.stagger : 0.05, order: 'forward', smoothing: 0 }, allWords.length) : null;
  const stag = anim ? (anim.stagger != null ? anim.stagger : 0.05) : 0;

  for (const wd of allWords) {
    const wInfo = timed ? timed[wd.idx] : null;
    const active = wInfo && srcT >= wInfo.start && srcT <= wInfo.end;
    const highlighted = !!wInfo && (st.progressiveHighlight ? srcT >= wInfo.start : active);
    const wordT0 = anim ? (wInfo ? wInfo.start : cue.start + offs[wd.idx]) : 0;

    if (anim && unit === 'letter') {
      // letters cascade from the moment their word is spoken
      let lx = wd.x;
      const chars = [...wd.text];
      for (let j = 0; j < chars.length; j++) {
        const chW = ctx.measureText(chars[j]).width;
        const pose = poseAt(wordT0 + j * stag, wd.idx * 31 + j);
        if (pose !== 'hidden') {
          ctx.save();
          if (pose) applyPose(pose, lx + chW / 2, wd.y - fontSize * 0.36);
          if (st.karaokePop) {
            const kScale = karaokeScale(active, wInfo);
            if (kScale !== 1) {
              const cxp = lx + chW / 2, cyp = wd.y - fontSize * 0.36;
              ctx.translate(cxp, cyp); ctx.scale(kScale, kScale); ctx.translate(-cxp, -cyp);
            }
          }
          paintText(chars[j], lx, wd.y, active, { x: lx, w: chW, idx: wd.idx, box: false }, highlighted);
          ctx.restore();
        }
        lx += chW;
      }
      continue;
    }

    let pose = null;
    if (anim) {
      pose = poseAt(wordT0, wd.idx);
      if (pose === 'hidden') continue;
    }
    ctx.save();
    const cxp = wd.x + wd.w / 2, cyp = wd.y - fontSize * 0.36;
    if (pose) applyPose(pose, cxp, cyp);
    if (st.karaokePop) {
      const kScale = karaokeScale(active, wInfo);
      if (kScale !== 1) {
        ctx.translate(cxp, cyp);
        ctx.scale(kScale, kScale);
        ctx.translate(-cxp, -cyp);
      }
    }
    paintText(wd.text, wd.x, wd.y, active, { x: wd.x, w: wd.w, idx: wd.idx }, highlighted);
    ctx.restore();
  }
  ctx.restore();
}
